    const currentLust = contentDesignAssistant_clamp(Number(player.lust) || 0, 0, maxLust);
    const lustSurvival = enemy.expectedLust > 0 ? Math.max(0, maxLust - currentLust) / enemy.expectedLust : Number.POSITIVE_INFINITY;
