                detail: [
                    Array.isArray(family.themeAxes) ? family.themeAxes.slice(0, 4).join('、') : '',
                    Array.isArray(family.canonicalActions) ? `招牌行动：${family.canonicalActions.slice(-3).map((entry) => entry.name || entry.id || entry).join('、')}` : '',
                ].filter(Boolean).join(' · '),
