            await wait(100);
        if (!hasMvuApi())
            throw new Error('等待 MUV 初始化超时，请确认卡内脚本已启用并完成内嵌世界书导入');
        if (options.requireBattleData === false)
            return;
        const dataDeadline = Date.now() + battleDataTimeoutMs;
